{"seg": "IBNASHUR:1:1", "konu": "besmele: 1:1'in Kur'an lafzı olması", "tur": "fikih", "alim": "İbn Âşûr", "alinti": "هو لفظ قرآني لأنه جزء آية من قوله تعالى", "ozet": "Müslümanlar arasında besmelenin Kur'an lafzı olduğunda ihtilaf yoktur; Neml 27:30'un bir parçasıdır.", "iddia": ["I5"], "iliski": "destek"}
{"seg": "IBNASHUR:1:1", "konu": "önemli işe besmeleyle başlama", "tur": "hadis", "alim": "İbn Âşûr (hadis olarak anar)", "alinti": "كل أمر ذي بال لا يُبدأ فيه بسم الله الرحمن الرحيم فهو أقطع", "ozet": "Önemli her iş besmelesiz başlanırsa eksik kalır; rivayet sünen ve müstedreklerde yok, hasen diye nitelenmiş.", "iddia": ["I3"], "iliski": "destek", "derece": "hasen denmiş; sünen ve müstedreklerde yok"}
{"seg": "IBNASHUR:1:1", "konu": "besmelenin Fâtiha'dan ayet sayılması: Mâlik görüşü", "tur": "fikih", "alim": "Mâlik, Evzâî, Medine, Şam ve Basra fakihleri", "alinti": "إلى أنها ليست بآية من أوائل السور لكنها جزء آية من سورة النمل", "ozet": "Besmele surelerin başında ayet değildir; yalnız Neml'deki ayetin parçasıdır.", "iddia": ["I5"], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "besmelenin Fâtiha'dan ayet sayılması: Şâfiî ilk kavil ve Ahmed", "tur": "fikih", "alim": "Şâfiî (bir kavli), Ahmed, İshâk, Ebû Sevr, Mekke ve Kûfe fakihleri", "alinti": "إلى أنها آية في أول سورة الفاتحة خاصة", "ozet": "Besmele yalnız Fâtiha'nın başında bir ayettir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "besmele her surenin ayeti: İbnü'l-Mübârek", "tur": "fikih", "alim": "Abdullah b. el-Mübârek, Şâfiî (ikinci ve esah kavli)", "alinti": "إلى أنها آية من كل سورة", "ozet": "Besmele Berâe dışında her surenin başında ayettir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "Bâkıllânî'nin delili: tevatür ya da ahad", "tur": "kelam", "alim": "Bâkıllânî (İbnü'l-Arabî ve Kâdî Abdülvehhâb ona uyar)", "alinti": "لو كانت التسمية من القرآن لكان طريق إثباتها إما التواتر أو الآحاد", "ozet": "Besmele Kur'an olsaydı tevatürle ya da ahadla sabit olurdu; tevatür ihtilafı önler, ahad ise Kur'an'ı zannî yapar.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "ihtilaf Kur'an olmama delilidir", "tur": "kelam", "alim": "İbnü'l-Arabî", "alinti": "يكفيك أنها ليست من القرآن الاختلافُ فيها", "ozet": "Hakkında ihtilaf edilmesi besmelenin (Fâtiha'dan) Kur'an olmadığına yeter.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "Gazzâlî'nin itirazı: mushafta yazılmış olması", "tur": "kelam", "alim": "Gazzâlî (el-Müstasfâ), Fahreddîn er-Râzî ona uyar", "alinti": "كون التسمية مكتوبة بخط القرآن يوهن كونها ليست من القرآن", "ozet": "Besmelenin mushaf hattıyla yazılması onun Kur'an olmadığı iddiasını zayıflatır; delil gerekir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "kasame hadisi (Mâlikîlerin birinci eser delili)", "tur": "hadis", "alim": "Mâlik (el-Muvatta', el-Alâ'dan, Ebû Hureyre'den)", "alinti": "قسمت الصلاة نصفين بيني وبين عبدي فنصفها لي ونصفها لعبدي ولعبدي ما سأل", "ozet": "Hadis-i kudsîde besmele anılmaz; Mâlikîler bunu besmelenin Fâtiha'dan olmadığına delil sayar.", "iddia": [], "iliski": "yeni", "derece": "Muvatta' rivayeti"}
{"seg": "IBNASHUR:1:1", "confirm": null, "konu": "Übey hadisi: namaza nasıl başlarsın", "tur": "hadis", "alim": "Übey b. Ka'b (Muvatta' ve Sahîhayn)", "alinti": "كيف تقرأ إذا افتتحت الصلاة", "ozet": "Übey Fâtiha'yı el-hamdü ile okuyup bitirir; besmele okumaz, Mâlikîlere göre delil.", "iddia": [], "iliski": "yeni", "derece": "Muvatta' ve Sahîhayn"}
{"seg": "IBNASHUR:1:1", "konu": "Enes hadisi: Hz. Peygamber, Ebû Bekir, Ömer besmele okumazdı", "tur": "hadis", "alim": "Enes b. Mâlik (Müslim, Ebû Dâvûd, Nesâî)", "alinti": "فكانوا يستفتحون بالحمد لله رب العالمين", "ozet": "Namazda el-hamdü ile başlarlar, kıraatin ne başında ne sonunda besmele anarlardı.", "iddia": [], "iliski": "yeni", "derece": "Müslim, Ebû Dâvûd, Nesâî"}
{"seg": "IBNASHUR:1:1", "konu": "Âişe hadisi: namaza tekbirle başlama", "tur": "hadis", "alim": "Âişe (Müslim, Ebû Dâvûd)", "alinti": "كان رسول الله يستفتح الصلاة بالتكبير", "ozet": "Hz. Peygamber namaza tekbirle, kıraate el-hamdü ile başlardı.", "iddia": [], "iliski": "yeni", "derece": "Müslim, Ebû Dâvûd"}
{"seg": "IBNASHUR:1:1", "konu": "Abdullah b. Muğaffel hadisi", "tur": "hadis", "alim": "Abdullah b. Muğaffel (Tirmizî, Nesâî)", "alinti": "فلم أسمع أحداً منهم يقول", "ozet": "Peygamber ve üç halife ile namaz kıldı, hiçbirinin besmele dediğini duymadı.", "iddia": [], "iliski": "yeni", "derece": "Tirmizî, Nesâî"}
{"seg": "IBNASHUR:1:1", "konu": "Medine ehlinin ameli", "tur": "fikih", "alim": "Mâlikî delil (İbn Âşûr aktarır)", "alinti": "عمل أهل المدينة", "ozet": "Mescid-i Nebevî'de Mâlik'e dek cehrî namazda besmelenin açıktan okunmadığı tevatürle sabittir; bu belirleyici delil sayılır.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "vahyin başlangıcı hadisi", "tur": "hadis", "alim": "Âişe (İbn Âşûr ek delil olarak anar)", "alinti": "فلم يقل فقال لي بسم الله الرحمن الرحيم", "ozet": "Cebrâil 'ikra' derken besmele söylemez; bu, besmelenin surelerin parçası olmadığına delil gösterilir.", "iddia": [], "iliski": "yeni", "derece": "kaynak hadisi merfû sayar"}
{"seg": "IBNASHUR:1:1", "konu": "besmele ayet olursa Rahmân-Rahîm tekrarı", "tur": "belagat", "alim": "İbn Âşûr (Râzî'den aktarır)", "alinti": "وذلك يوجب أن يتكرر لفظان وهما { الرحمن الرحيم }", "ozet": "Besmele Fâtiha'dan olsaydı Rahmân-Rahîm kısa aralıkla tekrarlanırdı; bu belagatte hoş değildir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "Râzî'nin cevabı: tekrar te'kid içindir", "tur": "belagat", "alim": "Fahreddîn er-Râzî", "alinti": "إن التكرار لأجل التأكيد كثير في القرآن", "ozet": "Kur'an'da te'kid için tekrar çoktur; Allah'ın rahmân ve rahîm oluşunu pekiştirmek en önemli işlerdendir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "İbn Âşûr'un Râzî'ye karşılığı", "tur": "belagat", "alim": "İbn Âşûr", "alinti": "لأنه لا منكر لكونه تعالى رحماناً رحيماً", "ozet": "Allah'ın rahmân-rahîm oluşunu inkâr eden yoktur, bu yüzden Fâtiha'da te'kid yeri yoktur; iki ad arasındaki yakınlık da tekrarı kusur yapar.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "Beyzâvî: tekrarın gerekçesi hamdin hak edilişi", "tur": "belagat", "alim": "Beyzâvî (Silkûtî'nin eleştirisiyle)", "alinti": "وأجاب البيضاوي بأن نكتة التكرير هنا هي تعليل استحقاق الحمد", "ozet": "Tekrarın nüktesi hamdi hak etmenin gerekçesini bildirmektir; İbn Âşûr bu cevabı tutarsız bulur.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "Şâfiî delili: Ebû Hureyre hadisi", "tur": "hadis", "alim": "Ebû Hureyre (Taberânî, İbn Merdeveyh, Beyhakî)", "alinti": "فاتحة الكتاب سبع آيات أولاهن", "ozet": "Fâtiha yedi ayettir, ilki besmeledir; İbn Âşûr rivayetin sahih sınıfına inmediğini söyler.", "iddia": [], "iliski": "yeni", "derece": "sahih rical çıkarmamış; Taberânî, İbn Merdeveyh, Beyhakî"}
{"seg": "IBNASHUR:1:1", "konu": "Şâfiî delili: Ümmü Seleme hadisi", "tur": "hadis", "alim": "Ümmü Seleme (Ebû Dâvûd, Ahmed, Beyhakî)", "alinti": "وقول أم سلمة قرأ رسول الله صلى الله عليه وسلم الفاتحة", "ozet": "Hz. Peygamber Fâtiha'yı okuyup besmeleyi ayet saymıştır; Tahâvî rivayeti inkıtâ ile eleştirir.", "iddia": [], "iliski": "yeni", "derece": "Ebû Dâvûd'da; bazı tarikleri sahihlenmiş; Tahâvî inkıtâ der"}
{"seg": "IBNASHUR:1:1", "konu": "Tahâvî'nin Ümmü Seleme eleştirisi", "tur": "hadis", "alim": "Tahâvî", "alinti": "ولم يثبت سماع ابن أبي مليكة من أم سلمة", "ozet": "İbn Ebî Müleyke'nin Ümmü Seleme'den işittiği sabit değildir; rivayet munkatıdır.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "Buhârî'deki Enes: kıraatte med", "tur": "hadis", "alim": "Enes (Buhârî)", "alinti": "ولا حجة في هذا لأن ضمير قرأ وضمير يمد عائدان إلى أنس", "ozet": "Enes'in besmeleyi med örneği olarak okuması besmelenin ayet olduğuna delil değildir.", "iddia": [], "iliski": "yeni", "derece": "Buhârî rivayeti"}
{"seg": "IBNASHUR:1:1", "konu": "Enes hadisi: Kevser suresi", "tur": "hadis", "alim": "Enes (Müslim); İbnü'l-Mübârek ve Şâfiî'nin delili", "alinti": "أنزلت عليَّ سورة آنفاً", "ozet": "Peygamber besmeleyle Kevser'i okur; İbn Âşûr bunun sureye ait okuma değil okumaya başlama olduğunu söyler.", "iddia": [], "iliski": "yeni", "derece": "Müslim rivayeti"}
{"seg": "IBNASHUR:1:1", "konu": "İbn Âşûr: besmele istiâze yerine geçer", "tur": "tefsir_dirayet", "alim": "İbn Âşûr", "alinti": "بل افتتح بها عند إرادة القراءة", "ozet": "Peygamber okumaya başlarken besmeleyi söylemiştir; besmele 'Allah'ın adıyla istiâze ederim' anlamıyla istiâzenin yerini tutar.", "iddia": ["I3"], "iliski": "genisletme"}
{"seg": "IBNASHUR:1:1", "konu": "Osman: Berâe ile Enfâl arasına besmele yazılmaması", "tur": "tarih", "alim": "İbn Abbâs ile Osman'ın konuşması (Ebû Dâvûd, Tirmizî)", "alinti": "ولم أكتب بينهما سطر بسم الله الرحمن الرحيم", "ozet": "Osman Berâe'yi Enfâl'in devamı sandığı için aralarına besmele yazmadı.", "iddia": [], "iliski": "yeni", "derece": "Ebû Dâvûd, Tirmizî (Tirmizî sahih demiş)"}
{"seg": "IBNASHUR:1:1", "konu": "besmelenin mushafta yazılış sebebi", "tur": "tarih", "alim": "İbn Âşûr", "alinti": "أنها كتبت للفصل بين السور ليكون الفصل مناسباً لابتداء المصحف", "ozet": "Besmele sureleri ayırmak için yazılmıştır; Zeyd'in Ebû Bekir zamanındaki sahifelerinde yoktu, Osman mushafında yazıldı.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "kurrâ: sure arasında besmele okumayanlar", "tur": "kiraat", "alim": "Verş (Nâfi'den), İbn Âmir, Ebû Amr, Hamza, Ya'kûb, Halef", "alinti": "فورش عن نافع في أشهر الروايات عنه", "ozet": "Bu kurrâ iki sure arasında besmele okumaz; besmele yazısı sure başlangıcının işareti sayılır.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "kurrâ: sure arasında besmele okuyanlar", "tur": "kiraat", "alim": "Kâlûn (Nâfi'den), İbn Kesîr, Âsım, Kisâî, Ebû Ca'fer", "alinti": "يبسملون بين السورتين سوى ما بين الأنفال وبراءة", "ozet": "Bu kurrâ Enfâl ile Berâe dışında sureler arasında besmele okur ve bunu kıraat sünneti sayar.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "besmelenin müteallakı: okurum", "tur": "nahiv", "alim": "İbn Âşûr", "alinti": "واعلم أن متعلق المجرور في { بسم الله } محذوف تقديره هنا أقرأ", "ozet": "Cer-mecrûrun müteallakı hazfedilmiştir, burada takdiri 'okurum'dur.", "iddia": ["I2"], "iliski": "genisletme"}
{"seg": "IBNASHUR:1:1", "konu": "hazfin sebebi: salih işlere başlarken sünnet", "tur": "nahiv", "alim": "İbn Âşûr", "alinti": "وسبب حذف متعلق المجرور أن البسملة سنت عند ابتداء الأعمال الصالحة", "ozet": "Besmele salih işlere başlarken sünnet olduğu için müteallak karineye dayanılarak icâz amacıyla hazfedilmiştir.", "iddia": ["I2", "I3"], "iliski": "destek"}
{"seg": "IBNASHUR:1:1", "konu": "Firavun'un sihirbazları ve cahiliye", "tur": "ayet_ayet", "alim": "İbn Âşûr (Keşşâf'tan)", "alinti": "وقالوا بعزة فرعون", "ozet": "Şuarâ 26:44'te sihirbazlar işe başlarken 'Firavun'un izzetiyle' der; cahiliye ehli işe 'Lât'ın adıyla, Uzzâ'nın adıyla' diye başlardı.", "iddia": ["I3"], "iliski": "destek"}
{"seg": "IBNASHUR:1:1", "konu": "zarf-ı lağv: müteallak fiil", "tur": "nahiv", "alim": "İbn Âşûr", "alinti": "فالمجرور ظرف لغو معمول للفعل المحذوف ومتعلق به", "ozet": "Cer-mecrûr zarf-ı lağvdır, hazfedilen fiilin ma'mulüdür; Basra-Kûfe'nin isim mi fiil mi takdiri tartışması burada işlemez.", "iddia": ["I1", "I2"], "iliski": "genisletme"}
{"seg": "IBNASHUR:1:1", "konu": "özel fiil takdiri hem özelleştirir hem yaygınlaştırır", "tur": "nahiv", "alim": "İbn Âşûr", "alinti": "فتقدير الفعل العام يخصص وتقدير الفعل الخاص يعمم", "ozet": "Müteallak olarak genel fiil ('başlıyorum') anlamı daraltır; işe uygun özel fiil takdiri her parçayı kapsar.", "iddia": ["I2"], "iliski": "genisletme"}
{"seg": "IBNASHUR:1:1", "konu": "hazfin faydası: her iş için kullanılabilir", "tur": "belagat", "alim": "İbn Âşûr", "alinti": "وقد أسعف هذا الحذف بفائدة وهي صلوحية البسملة ليَبتَدِىءَ بها كلُّ شارع في فعل", "ozet": "Fiilin düşmesi, her işe başlayanın Kur'an lafzını değiştirmeden besmeleyi kullanmasını sağlar; hazf icâz türündendir.", "iddia": ["I2", "I3"], "iliski": "destek"}
{"seg": "IBNASHUR:1:1", "konu": "müteallakın öne takdiri; Zemahşerî eleştirisi", "tur": "nahiv", "alim": "İbn Âşûr (Zemahşerî'ye karşı)", "alinti": "ودعوى صاحب « الكشاف » تقديره مُؤخراً تعمق غير مقبول", "ozet": "Hasr kastı olmadığı için müteallak sonda değil asıl sırayla öne takdir edilir; Zemahşerî'nin sonra takdiri aşırıya kaçmadır.", "iddia": ["I2"], "iliski": "genisletme"}
{"seg": "IBNASHUR:1:1", "konu": "bâ: mülâbese, musâhabe, ilsâk", "tur": "nahiv", "alim": "İbn Âşûr; Sîbeveyh", "alinti": "والباء باء الملابسة", "ozet": "Bâ mülâbese bâsıdır; mülâbese, musâhabe ve ilsâk aynı anlamdadır ve bâ'nın en yaygın anlamıdır.", "iddia": ["I1"], "iliski": "destek"}
{"seg": "IBNASHUR:1:1", "konu": "Zemahşerî: mülâbese vechi araç bâsından üstün", "tur": "nahiv", "alim": "Zemahşerî (İbn Âşûr aktarır)", "alinti": "أي أحسن من جعل الباء للآلة", "ozet": "Bâ'yı mülâbese saymak onu alet (araç) sayandan daha güzeldir; eylemin her parçasının Allah'ın adıyla birlikteliğini bereket sayar.", "iddia": ["I1"], "iliski": "genisletme"}
{"seg": "IBNASHUR:1:1", "konu": "ism kelimesi: Basra, sümüvv", "tur": "lugat", "alim": "Basra imamları", "alinti": "وجعله أئمة البصرة مشتقاً من السمو وهو الرفعة", "ozet": "Basralılar ismi yükseklik anlamındaki sümüvvden türetir; isim asılda ilgilenilen şeye konan alemdir.", "iddia": ["I13", "I15"], "iliski": "destek"}
{"seg": "IBNASHUR:1:1", "konu": "ism: Basra'nın sarf delilleri", "tur": "lugat", "alim": "Basralılar", "alinti": "وقد احتجوا على أن أصله كذلك بجمعه على أسماء بوزن أفعال", "ozet": "Çoğul esmâ, çoğulun çoğulu esâmî ve küçültme sumey, aslın vav-nâkıs olduğunu gösterir.", "iddia": ["I27"], "iliski": "destek"}
{"seg": "IBNASHUR:1:1", "konu": "ism: Kûfe, vesm", "tur": "lugat", "alim": "Kûfeliler", "alinti": "وذهب الكوفيون إلى أن أصله وِسْم بكسر الواو لأنه من السمة وهي العَلامة", "ozet": "Kûfeliler ismin aslının vesm olduğunu, vâvın düşüp hemze-i vaslın geldiğini söyler.", "iddia": ["I30"], "iliski": "destek"}
{"seg": "IBNASHUR:1:1", "konu": "ism: Kûfe görüşü iştikakta, Basra tasrifte güçlü", "tur": "lugat", "alim": "İbn Âşûr", "alinti": "ورأي الكوفيين أرجح من جانب الاشتقاق دون التصريف", "ozet": "Kûfe görüşü türetme yönünden, Basra görüşü sarf yönünden daha güçlüdür; sarf çekimleri asıl-zâid ayrımını belirler.", "iddia": ["I30"], "iliski": "genisletme"}
{"seg": "IBNASHUR:1:1", "konu": "Basra görüşü sarf bakımından tercih", "tur": "lugat", "alim": "İbn Âşûr", "alinti": "ورَأْيُ البصريين أرجح من ناحية تصاريف هذا اللفظ", "ozet": "Basra görüşü kelimenin çekimleri bakımından daha güçlüdür.", "iddia": ["I27", "I30"], "iliski": "destek"}
{"seg": "IBNASHUR:1:1", "konu": "İbn Hazm: ism câmiddir", "tur": "lugat", "alim": "İbn Hazm (el-Milel)", "alinti": "أن لفظ الاسم غير مشتق بل هو جامد", "ozet": "İbn Hazm iki görüşü de nahivcilerin uydurması sayar, ismin türetilmediğini söyler; İbn Âşûr bunu küstahlık sayar.", "iddia": ["I13", "I30"], "iliski": "karsi"}
{"seg": "IBNASHUR:1:1", "konu": "neden 'bi-ismillâh' da 'billâh' değil", "tur": "belagat", "alim": "İbn Âşûr", "alinti": "ولم يقل بالله لأن المقصود أن يكون الفعل المشروع فيه من شؤون أهل التوحيد", "ozet": "'İsim' sözü, iş tevhid ehline ait olsun ve Allah'ın adıyla anılsın diye eklenir; 'billâh' Allah'tan yardım istemek olurdu.", "iddia": ["I3", "I10"], "iliski": "genisletme"}
{"seg": "IBNASHUR:1:1", "konu": "kesimde ve işe başlamada ismin kullanımı", "tur": "ayet_ayet", "alim": "İbn Âşûr", "alinti": "فكلوا مما ذكر اسم الله عليه", "ozet": "En'âm 6:118-119'daki kesim tesmiyesi ile 96:1 gibi bereket ve yardım amaçlı işlerde 'isim' kelimesi eklenir.", "iddia": ["I9"], "iliski": "destek"}
{"seg": "IBNASHUR:1:1", "konu": "ismullah anılır, zât değil", "tur": "tefsir_dirayet", "alim": "İbn Âşûr", "alinti": "فاسم الله هو الذي تمكن مقارنته للأفعال لا ذاته", "ozet": "Eylemlere eşlik edebilen Allah'ın adıdır, zâtı değildir; 'billâh' ise güç ve tasarruftan yardım alma anlamı verirdi.", "iddia": ["I1", "I3"], "iliski": "genisletme"}
{"seg": "IBNASHUR:1:1", "konu": "ismin kabile işareti ve şiarla benzetilmesi", "tur": "belagat", "alim": "İbn Âşûr", "alinti": "فاستعمال لفظ الاسم في هذا بمنزلة استعمال سمات الإبل عند القبائل", "ozet": "Burada 'isim' kullanımı kabilelerin develerine vurduğu damga ve orduların şiarı gibidir.", "iddia": ["I31", "I32"], "iliski": "destek"}
{"seg": "IBNASHUR:1:1", "konu": "Hûd 11:41 ve sabah-akşam duası", "tur": "ayet_ayet", "alim": "İbn Âşûr", "alinti": "وقال اركبوا فيها بسم الله مجراها ومرساها", "ozet": "Hûd 11:41 ve yatış duası ('bismike rabbî vada'tu cenbî') teyemmün ve Rab'be intisap makamında fiilin ismullaha geçirildiğini gösterir.", "iddia": ["I7"], "iliski": "destek"}
{"seg": "IBNASHUR:1:1", "konu": "besmelenin anlamı", "tur": "tefsir_dirayet", "alim": "İbn Âşûr", "alinti": "أقرأ قراءة ملابسة لبركة هذا", "ozet": "Besmelenin anlamı: bu mübarek adın bereketiyle birlikte okurum.", "iddia": ["I1", "I2"], "iliski": "destek"}
{"seg": "IBNASHUR:1:1", "konu": "ism sözünün müsemmâ anlamında kullanımı: Nâbiğa", "tur": "lugat", "alim": "İbn Âşûr (Nâbiğa şiiri)", "alinti": "نبئتُ زُرعة والسفاهةُ كاسمها", "ozet": "Arapların ismi müsemmâ yerine kullanması: sefâhet adından başka bir şeyle tanıtılmaz.", "iddia": ["I19"], "iliski": "genisletme"}
{"seg": "IBNASHUR:1:1", "konu": "ism sözünün sıla olarak fazladan kullanımı: Lebîd", "tur": "lugat", "alim": "İbn Âşûr (Lebîd şiiri)", "alinti": "ويطلقون الاسم مقحماً زائداً كما في قول لبيد", "ozet": "Lebîd'in 'sümme ismü's-selâm aleykumâ' beytinde ism fazladır, 'selâm' demektir.", "iddia": ["I19"], "iliski": "genisletme"}
{"seg": "IBNASHUR:1:1", "konu": "ismin müsemmânın varlığına kinaye olması", "tur": "lugat", "alim": "İbn Âşûr", "alinti": "وقد يطلق الاسم وما في معناه كنايةً عن وجود المسمى", "ozet": "Ra'd 13:33'teki 'onlara ad verin' ortakların varlığını ve ad konmasını ispat etmek anlamındadır; besmeledeki ism bu türden değildir.", "iddia": ["I19", "I28"], "iliski": "genisletme"}
{"seg": "IBNASHUR:1:1", "konu": "besmelede bâ harfinin uzatılması", "tur": "tarih", "alim": "İbn Âşûr", "alinti": "طولوها في سورة النمل للإشارة إلى أنها مبدأ كتاب سليمان", "ozet": "Sahâbe bâ'yı Neml'de Süleyman'ın mektubunun başlangıcını göstermek için uzatmış, sure başlarına aynı resimle nakletmiştir.", "iddia": ["I5", "I32"], "iliski": "genisletme"}
{"seg": "IBNASHUR:1:1", "konu": "Allah, Rahmân, Rahîm bir arada: Beyzâvî", "tur": "tefsir_dirayet", "alim": "Beyzâvî", "alinti": "ثم يذكر وصف الرحمن إشارة إلى أن الاستعانة على الأعمال الصالحة وهي نعم", "ozet": "Alem zâtın yardım hakkına, Rahmân sıfatı da yardımın salih işlere (nimetlere) olduğuna işaret eder; Rahîm'in gerekçeleri sonra gelir.", "iddia": ["I1"], "iliski": "genisletme"}
{"seg": "IBNASHUR:1:1", "konu": "Muhammed Abduh: Hıristiyanlara reddiye", "tur": "tefsir_dirayet", "alim": "Muhammed Abduh", "alinti": "إن النصارى كانوا يبتدئون أدعيتهم ونحوها باسم الأب والابن والروح القدس", "ozet": "Hıristiyanlar dualarına Baba, Oğul, Ruhulkudüs adıyla başlardı; besmele, ilâhın tek olduğunu, adların çokluğunun sıfat çokluğu olduğunu bildirir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "besmelenin İbrahim'e dayanan sünnet olması", "tur": "tarih", "alim": "İbn Âşûr", "alinti": "وعندي أن البسملة كان ما يرادفها قد جرى على ألسنة الأنبياء من عهد إبراهيم عليه السلام", "ozet": "Besmelenin eşdeğeri İbrahim'den beri peygamberlerin dilindeydi (Meryem 19:45); Süleyman'ın mektubu bu mirasa uyar, İslam bu sünneti diriltir.", "iddia": ["I5"], "iliski": "genisletme"}
{"seg": "IBNASHUR:1:1", "konu": "besmele fiili: nahtın bir örneği", "tur": "lugat", "alim": "İbn Âşûr; Ömer b. Ebî Rebîa", "alinti": "لقد بسملت ليلَى غداةَ لقيتُها", "ozet": "'Besmele' (besmele çekmek) nahtla 'bismillâh' sözünden türemiş fiildir; Ömer b. Ebî Rebîa beytinde ismi fâil de geçer.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "nahtla türeyen yedi fiil", "tur": "lugat", "alim": "el-Mutarrizî (Yevâkît'ten, İbn Hârûn et-Tûnisî aracılığıyla)", "alinti": "الأفعالُ التي نحتت من أسمائها سبعة", "ozet": "Nahtla kısaltılmış fiiller arasında besmele sözünden 'besmele' de vardır (sübhale, hayale, havkale, hamdele, hellele gibi).", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "Fâtiha'nın yedi ayet olması ve besmele sayımı", "tur": "kiraat", "alim": "İbn Âşûr; Medine, Mekke, Kûfe ve Hasan el-Basrî", "alinti": "فعند أهل المدينة لا تعد البسملة آية وتعد { أنعمت عليهم } آية", "ozet": "Medineliler besmeleyi ayet saymaz, 'en'amte aleyhim'i sayar; Mekke ve Kûfeliler besmeleyi sayar; Hasan her ikisini sayar.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "Fâtiha'da ayet sayısı ihtilafı", "tur": "kiraat", "alim": "Hasan el-Basrî (sekiz); Hüseyin el-Cu'fî (altı)", "alinti": "ولم يشذ عن ذلك إلا الحسن البصري فقال هي ثمان آيات", "ozet": "Ayet sayısında kurrâ ve müfessirlerin yedi ittifakından yalnız Hasan sekiz, Cu'fî altı der; besmele sayılmazsa yedi çıkması için bazı dokuz ayet der.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR:1:1", "konu": "kasame hadisinde Fâtiha'nın bölünüşü", "tur": "hadis", "alim": "Ebû Hureyre (Sahîhayn)", "alinti": "قسمت الصلاة نصفين بيني وبين عبدي فنصفها لي ونصفها لعبدي", "ozet": "Hadis-i kudsîde Fâtiha hamd, sena (Rahmân-Rahîm), mecd, ortak ve kulun isteği olarak bölünür; besmele anılmaz.", "iddia": [], "iliski": "yeni", "derece": "Sahîhayn rivayeti"}
{"seg": "IBNASHUR:1:1", "konu": "Rahmân-Rahîm Allah'ın senası", "tur": "hadis", "alim": "Ebû Hureyre (Sahîhayn)", "alinti": "يقول الله أثنى علي عبدي", "ozet": "Kul 'er-Rahmâni'r-Rahîm' dediğinde Allah 'kulum bana sena etti' der.", "iddia": [], "iliski": "yeni", "derece": "Sahîhayn rivayeti"}
{"seg": "IBNASHUR:1:1", "konu": "Rahmân-Rahîm: şeriata dönen rahmet", "tur": "tefsir_dirayet", "alim": "İbn Âşûr", "alinti": "و{ الرحمن الرحيم } يشمل أصول التشريع الراجعة للرحمة بالمكلفين", "ozet": "Rahmân-Rahîm, mükelleflere rahmet olarak dönen tüm teşri' esaslarını kapsar.", "iddia": ["I64"], "iliski": "yeni"}
{"seg": "IBNASHUR-FULL:v1p142#2", "konu": "icmâ ve mushaf yazısı", "tur": "fikih", "alim": "İbn Âşûr", "alinti": "إلا أن البسملة قرآن وهذا لانزاع فيه", "ozet": "'Kapaklar arası Allah'ın kelâmıdır' icmâı besmelenin Kur'an olduğunu gösterir, okunma yerlerini belirlemez; o kurrâ rivayetine ve sahih sünnete bağlıdır.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR-FULL:v1p142#2", "konu": "mushaf yazısına dayanmanın reddi", "tur": "tarih", "alim": "İbn Âşûr", "alinti": "فالاحتجاج حينئذ بالكتابة باطل من أصله", "ozet": "Selefin sure adlarını yazdığı sabitse mushaf yazısı delil olamaz; selef mushaflarında mürekkep tek renktir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNASHUR-FULL:v1p142#2", "konu": "Buhârî'deki Enes rivayeti: med", "tur": "hadis", "alim": "Enes (Buhârî)", "alinti": "ولا حجة في هذا لأن ضمير قرأ وضمير يمد عائدان إلى أنس", "ozet": "Enes besmeleyi kıraatin nasıl olduğunu örneklemek için okumuştur; delil değildir.", "iddia": [], "iliski": "yeni", "derece": "Buhârî rivayeti"}
{"seg": "IBNASHUR-FULL:v1p142#2", "konu": "Müslim'deki Enes rivayeti: Kevser", "tur": "hadis", "alim": "Enes (Müslim); İbnü'l-Mübârek ve Şâfiî'nin ikinci kavli", "alinti": "ولذلك لم يكتبوا آمين في الفاتحة", "ozet": "Sahâbenin mushafa Kur'an olmayanı sokmaktan kaçındığı, bu yüzden 'âmîn'i yazmadığı, besmeleyi yazdığı delil gösterilir.", "iddia": [], "iliski": "yeni", "derece": "Müslim rivayeti"}
{"seg": "IBNASHUR-FULL:v1p146", "konu": "besmelenin müteallakı: okurum", "tur": "nahiv", "alim": "İbn Âşûr", "alinti": "واعلم أن متعلق المجرور في { بسم الله } محذوف تقديره هنا أقرأ", "ozet": "Müteallak hazfedilmiştir, takdiri 'okurum'dur; hazf iltizâmî ve icâz içindir.", "iddia": ["I2"], "iliski": "genisletme"}
{"seg": "IBNASHUR-FULL:v1p146", "konu": "Şuarâ 26:44 ve cahiliye şiarı", "tur": "ayet_ayet", "alim": "İbn Âşûr (Keşşâf'tan)", "alinti": "باسم اللاتت باسم العزى", "ozet": "Cahiliye ehli işe 'Lât adıyla, Uzzâ adıyla' başlar; Firavun'un sihirbazları 'Firavun'un izzetiyle' der (26:44).", "iddia": ["I3"], "iliski": "destek"}
{"seg": "IBNASHUR-FULL:v1p146", "konu": "zarf-ı lağv", "tur": "nahiv", "alim": "İbn Âşûr", "alinti": "وليس ظرفا مستقرا", "ozet": "Cer-mecrûr fiile bağlı zarf-ı lağvdır, haber olan zarf-ı müstakarr değildir; bu yüzden isim-fiil takdiri tartışması geçerli değildir.", "iddia": ["I1", "I2"], "iliski": "genisletme"}
{"seg": "IBNASHUR-FULL:v1p146", "konu": "özel fiil takdiri", "tur": "nahiv", "alim": "İbn Âşûr", "alinti": "فتقدير الفعل العام يخصص وتقدير الفعل الخاص يعمم", "ozet": "Genel fiil takdiri anlamı özelleştirir; işe uygun özel fiil takdiri her parçaya bereketi yayar.", "iddia": ["I2"], "iliski": "genisletme"}
{"seg": "IBNASHUR-FULL:v1p146", "konu": "karinelerle takdir edilen cümleler", "tur": "belagat", "alim": "İbn Âşûr", "alinti": "وهذا التقدير من المقدرات التي دلت عليها القرائن", "ozet": "Düğünde 'bi'r-rifâ' ve yolculukta 'bismillâhi ve'l-berekât' gibi karineyle takdir edilen söylemlerden biridir.", "iddia": ["I2"], "iliski": "destek"}
{"seg": "IBNASHUR-FULL:v1p149", "konu": "ism sözünün eklenme sebebi", "tur": "belagat", "alim": "İbn Âşûr", "alinti": "فاسم الله هو الذي تمكن مقارنته للأفعال لا ذاته", "ozet": "Eylemlere eşlik edebilen Allah'ın adıdır; 'billâh' deyince kudretinden yardım istemek anlamı çıkardı, ki bu kastedilen değildir.", "iddia": ["I1", "I3"], "iliski": "genisletme"}
{"seg": "IBNASHUR-FULL:v1p149", "konu": "kesim tesmiyesi", "tur": "ayet_ayet", "alim": "İbn Âşûr", "alinti": "فكلوا مما ذكر اسم الله عليه", "ozet": "En'âm 6:118 ve 119, kesim üzerinde ismin anılmasını örnekler; 'isim' kelimesi tevhid ehline ait işlerde eklenir.", "iddia": ["I9"], "iliski": "destek"}
{"seg": "IBNASHUR-FULL:v1p149", "konu": "Vâkıa 56:74 ve sebbih emri", "tur": "ayet_ayet", "alim": "İbn Âşûr", "alinti": "أمر بأن يقول سبحان الله", "ozet": "'Rabbinin adıyla tesbih et' (56:74) 'sübhânallah de' emridir; ism kelimesi zikir makamında kullanılır.", "iddia": ["I6"], "iliski": "destek"}
{"seg": "IBNASHUR-FULL:v1p149", "konu": "kabile işareti benzetmesi", "tur": "belagat", "alim": "İbn Âşûr", "alinti": "بمنزلة استعمال سمات الإبل عند القبائل", "ozet": "İsim kullanımı kabilelerin develerine damga vurması ve orduların şiarı gibidir.", "iddia": ["I31"], "iliski": "destek"}
{"seg": "IBNASHUR-FULL:v1p149", "konu": "Hûd 11:41 ve yatış duası", "tur": "ayet_ayet", "alim": "İbn Âşûr", "alinti": "وقال اركبوا فيها بسم الله مجراها ومرساها", "ozet": "Teyemmün ve Rab'be intisap makamında fiil ismullaha geçirilir: Hûd 11:41 ve 'bismike rabbî vada'tu cenbî' duası.", "iddia": ["I7"], "iliski": "destek", "derece": "kaynak derece vermiyor"}
{"seg": "IBNASHUR-FULL:v1p149", "konu": "yardım isteme makamında zâtın alemi", "tur": "belagat", "alim": "İbn Âşûr", "alinti": "اللهم بك نصبح وبك نمسي", "ozet": "Yardım ve kolaylık istenen makamda fiil zâtın alemine geçirilir: 'bike nusbihu' kudret ve meşiet anlamındadır.", "iddia": [], "iliski": "yeni", "derece": "kaynak derece vermiyor"}
{"seg": "IBNASHUR-FULL:v1p149", "konu": "besmelenin anlamı", "tur": "tefsir_dirayet", "alim": "İbn Âşûr", "alinti": "أقرأ قراءة ملابسة لبركة هذا الاسم المبارك", "ozet": "Besmelenin anlamı: bu mübarek adın bereketiyle birlikte okurum.", "iddia": ["I1", "I2"], "iliski": "destek"}
{"seg": "IBNATIYYA:1:1", "konu": "Hz. Ca'fer es-Sâdık: besmele sure tacı", "tur": "tefsir_rivayet", "alim": "Cafer b. Muhammed es-Sâdık", "alinti": "البسملة تيجان السور", "ozet": "Besmele surelerin taçlarıdır.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA:1:1", "konu": "şeytanı küçülten besmele", "tur": "hadis", "alim": "Hz. Peygamber (adam 'te'isa'ş-şeytân' deyince)", "alinti": "فإنه يتعاظم عنده ولكن قل بسم الله الرحمن الرحيم فإنه يصغر حتى يصير أقل من ذباب", "ozet": "'Şeytan helak olsun' deme, o büyür; 'bismillâhi'r-rahmâni'r-rahîm' de, sinekten küçük olur.", "iddia": [], "iliski": "yeni", "derece": "kaynak derece vermiyor"}
{"seg": "IBNATIYYA:1:1", "konu": "İsrâ 17:46 tefsiri: besmele", "tur": "tefsir_rivayet", "alim": "Ali b. el-Hüseyin (Zeynelâbidîn)", "alinti": "قال معناه إذا قلت بسم الله الرحمن الرحيم", "ozet": "'Rabbini Kur'an'da yalnız andığında sırtlarını dönüp kaçarlar' ayetinin anlamı: besmele dediğinde.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA:1:1", "konu": "Câbir hadisi: namaza besmeleyle başla", "tur": "hadis", "alim": "Câbir b. Abdullah", "alinti": "كيف تفتتح الصلاة يا جابر قلت بالحمد لله رب العالمين قال قل بسم الله الرحمن الرحيم", "ozet": "Peygamber Câbir'e namaza nasıl başladığını sorar, 'el-hamdü ile' deyince 'besmele de' der.", "iddia": ["I3"], "iliski": "destek", "derece": "kaynak derece vermiyor (İbn Atiyye 'sahih olursa' der)"}
{"seg": "IBNATIYYA:1:1", "konu": "Cebrâil namazı öğretirken besmeleyi cehren okur", "tur": "hadis", "alim": "Ebû Hureyre", "alinti": "أتاني جبريل فعلمني الصلاة فقرأ بسم الله الرحمن الرحيم يجهر بها", "ozet": "Cebrâil namazı öğretirken besmeleyi açıktan okur.", "iddia": [], "iliski": "yeni", "derece": "kaynak derece vermiyor (İbn Atiyye 'sahih olursa' der)"}
{"seg": "IBNATIYYA:1:1", "konu": "İbn Atiyye: bu iki hadis ayet olduğunu gerektirir, Übey hadisi reddeder", "tur": "fikih", "alim": "İbn Atiyye", "alinti": "وهذان الحديثان يقتضيان أنها آية من الحمد", "ozet": "Câbir ve Ebû Hureyre hadisleri besmelenin Fâtiha'dan ayet olduğunu gösterir görünür; sahih Übey hadisi, kasame hadisi, halifelerin ameli ve ayet sayısı bunu reddeder.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA:1:1", "konu": "Übey hadisi", "tur": "hadis", "alim": "Übey b. Ka'b (İbn Atiyye 'sahih' der)", "alinti": "هل لك ألا تخرج من المسجد حتى تعلم سورة", "ozet": "Peygamber Übey'e eşsiz bir sure öğretir; Übey namaza başlarken yalnız el-hamdü'yü okur, besmele anmaz.", "iddia": [], "iliski": "yeni", "derece": "sahih (İbn Atiyye)"}
{"seg": "IBNATIYYA:1:1", "konu": "ayet sayısı delili", "tur": "fikih", "alim": "İbn Atiyye", "alinti": "ويرده عدد آيات السورة لأن الإجماع أنها سبع آيات", "ozet": "Ayet sayısı icmâla yedidir; Hüseyin el-Cu'fî'nin altı ve Amr b. Ubeyd'in sekiz demesi şâzdır.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA:1:1", "konu": "Hicr 15:87 yedi ayeti kesin kılar", "tur": "ayet_ayet", "alim": "İbn Atiyye", "alinti": "وقول الله تعالى { ولقد آتيناك سبعا من المثاني } هو الفصل في ذلك", "ozet": "'Sana yedi mesânî verdik' ayeti ayet sayısı konusunda hükmü verir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA:1:1", "konu": "Şâfiî", "tur": "fikih", "alim": "Şâfiî", "alinti": "والشافعي رحمه الله يعد بسم الله الرحمن الرحيم آية من الحمد", "ozet": "Şâfiî besmeleyi Fâtiha'dan bir ayet sayar; Mekke ve Kûfe kurrâsından çoğu 'en'amte aleyhim'i saymaz.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA:1:1", "konu": "Mâlik, Ebû Hanîfe ve cumhur", "tur": "fikih", "alim": "Mâlik, Ebû Hanîfe, fakih ve kurrâ cumhuru", "alinti": "ومالك رحمه الله وأبو حنيفة وجمهور الفقهاء والقراء لا يعدون البسملة آية", "ozet": "Cumhur besmeleyi ayet saymaz.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA:1:1", "konu": "İbn Atiyye: Câbir ve Ebû Hureyre hadislerinin yorumu", "tur": "fikih", "alim": "İbn Atiyye", "alinti": "فأمره بالبسملة لهذا لا لأنها آية", "ozet": "Peygamber Câbir'in okumasını öğrenme amaçlı saydığı için besmeleyi emreder, ayet olduğu için değil; Übey'e sureyi özel kılmak istediği için söylemez.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA:1:1", "konu": "İbnü'l-Mübârek", "tur": "fikih", "alim": "İbnü'l-Mübârek", "alinti": "وهذا قول شاذ رد الناس عليه", "ozet": "'Besmele her surede ayettir' görüşü şâzdır, insanlar reddetmiştir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA:1:1", "konu": "Peygamber 'bismike'llâhümme'den 'bismillâh'a ve 'er-Rahmân'a', Neml 27:30'a", "tur": "nuzul", "alim": "eş-Şa'bî ve el-A'meş", "alinti": "فلما نزلت { قل ادعوا الله أو ادعوا الرحمن } كتب بسم الله الرحمن", "ozet": "Peygamber önce 'bismike'llâhümme' yazar, sonra 'bismillâh'; İsrâ 110 inince 'bismillâhi'r-Rahmân'; Neml 30 inince tam besmeleyi yazar.", "iddia": ["I5", "I25"], "iliski": "genisletme"}
{"seg": "IBNATIYYA:1:1", "konu": "besmele ilk vahiy olarak", "tur": "nuzul", "alim": "Amr b. Şurahbîl", "alinti": "أن جبريل أول ما جاء النبي صلى الله عليه وسلم قال له قل بسم الله الرحمن الرحيم", "ozet": "Cebrâil ilk geldiğinde Peygamber'e 'besmele de' der.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA:1:1", "konu": "İbn Abbâs: Cebrâil'in ilk getirdiği besmele", "tur": "nuzul", "alim": "İbn Abbâs", "alinti": "أن أول ما نزل به جبريل بسم الله الرحمن الرحيم", "ozet": "Cebrâil'in ilk indirdiği söz besmeledir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA:1:1", "konu": "Hatice hadisinin bazı tarikleri", "tur": "hadis", "alim": "Hatice hadisinin bazı tarikleri", "alinti": "جبريل قال للنبي عليهما السلام قل بسم الله الرحمن الرحيم فقالها", "ozet": "Bazı yollarda Cebrâil 'besmele de' der, Peygamber söyler, sonra 'ikra' denir.", "iddia": [], "iliski": "yeni", "derece": "kaynak derece vermiyor"}
{"seg": "IBNATIYYA:1:1", "konu": "besmele on dokuz harftir; zebâniler", "tur": "isari", "alim": "bazı kimseler (İbn Atiyye aktarır)", "alinti": "والبسملة تسعة عشر حرفا", "ozet": "Besmele on dokuz harftir; bazıları cehennem zebânilerinin on dokuz sayısını (74:30) bu harflere bağlar; her harfe bir melek, güçleri besmeledendir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA:1:1", "konu": "İbn Atiyye: harf sayısı yorumu tefsir tuzlasıdır", "tur": "tefsir_dirayet", "alim": "İbn Atiyye", "alinti": "وهذه من ملح التفسير وليست من متين العلم", "ozet": "Bu, tefsirin nüktelerindendir, sağlam ilimden değildir; Kadir gecesinin yirmi yedinci gece oluşu gibi harf sayımına dayanır.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA:1:1", "konu": "bâ'nın müteallakı: Basra", "tur": "nahiv", "alim": "Basra nahivcileri", "alinti": "والباء في بسم الله متعلقة عند نحاة البصرة", "ozet": "Basralılara göre bâ isme bağlıdır, takdir 'başlangıcım yerleşiktir/sabittir bismillâh'; bismillâh merfû mahallindedir.", "iddia": ["I2"], "iliski": "karsi"}
{"seg": "IBNATIYYA:1:1", "konu": "bâ'nın müteallakı: Kûfe", "tur": "nahiv", "alim": "Kûfe nahivcileri", "alinti": "وعند نحاة الكوفة بفعل تقديره", "ozet": "Kûfelilere göre bâ fiile bağlıdır, takdir 'başladım bismillâh'; bismillâh mansûb mahallindedir.", "iddia": ["I2"], "iliski": "destek"}
{"seg": "IBNATIYYA:1:1", "konu": "bâ'nın kesrelenmesi", "tur": "nahiv", "alim": "İbn Atiyye", "alinti": "وكسرت باء الجر ليناسب لفظها عملها", "ozet": "Cer bâsı lafzı amelle uyuşsun diye, yalnız isimlere girdiği için ya da harf-ism ayrımı için kesrelenmiştir.", "iddia": ["I1"], "iliski": "yeni"}
{"seg": "IBNATIYYA:1:1", "konu": "bismillâh'ta elifin yazıda düşmesi", "tur": "nahiv", "alim": "İbn Atiyye; el-Kisâî, el-Ahfeş, Yahya b. Ziyâd", "alinti": "وحذفت الألف من بسم الله في الخط اختصارا وتخفيفا لكثرة الاستعمال", "ozet": "Elif sık kullanımdan yazıda düşer; Kisâî ve Ahfeş 'bismi'r-Rahmân'da da düşer der, Yahya yalnız 'bismillâh'ta der.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA:1:1", "konu": "ism: Basra sümüvv", "tur": "lugat", "alim": "Basralılar", "alinti": "وهو عند البصريين مشتق من السمو", "ozet": "Basralılara göre ism sümüvvden türetilmiştir; asıl simv ya da sumv'dur, vâv düşmüştür.", "iddia": ["I13", "I27"], "iliski": "destek"}
{"seg": "IBNATIYYA:1:1", "konu": "ism: çekimlerden delil", "tur": "lugat", "alim": "Basralılar", "alinti": "وفي جمع الجمع", "ozet": "Küçültme sumey, çoğul esmâ ve çoğulun çoğulu esâmî, ismin sümüvv aslından olduğuna delildir.", "iddia": ["I27"], "iliski": "destek"}
{"seg": "IBNATIYYA:1:1", "konu": "ism: Kûfe vesm", "tur": "lugat", "alim": "Kûfeliler", "alinti": "أصل اسم وسم من السمة وهي العلامة", "ozet": "Kûfelilere göre ism vesmden gelir, çünkü isim konulan şeyin alametidir; İbn Atiyye küçültme ve çoğul bunu çürütür, anlamı güzel olsa da der.", "iddia": ["I30", "I31"], "iliski": "genisletme"}
{"seg": "IBNATIYYA:1:1", "konu": "ism ve müsemmâ: Taberî", "tur": "kelam", "alim": "et-Taberî (İbn Atiyye aktarır)", "alinti": "إنه ليس بموضع للمسألة", "ozet": "Taberî bunun yeri olmadığını söyler, kelamcılara hücum eder; İbn Atiyye yine de ismin bazen zâtı, bazen sözün kendisini kastettiğini ayırır.", "iddia": ["I19"], "iliski": "destek"}
{"seg": "IBNATIYYA:1:1", "konu": "ismin zât anlamında kullanımı", "tur": "lugat", "alim": "İbn Atiyye", "alinti": "الاسم هو المسمى بمعنى يراد به المسمى", "ozet": "İsim bazen zâtı kastedince 'ism müsemmânın kendisidir'; bazen adın kendisi kastedilince değildir ('Rahmân' Allah'ın sıfatıdır).", "iddia": ["I19"], "iliski": "destek"}
{"seg": "IBNATIYYA:1:1", "konu": "ism, zât, nefs, ayn eş anlamlı", "tur": "lugat", "alim": "İbn Atiyye; ehl-i ilmin çoğu", "alinti": "يقال ذات ونفس واسم وعين بمعنى", "ozet": "A'lâ 87:1, Rahmân 55:78 ve Yûsuf 12:40 ayetleri çoğunlukla ismi zât anlamına alır; Lebîd beyti 'selâm' anlamını destekler.", "iddia": ["I18", "I28"], "iliski": "destek"}
{"seg": "IBNATIYYA:1:1", "konu": "ismin lafız olarak kullanımı: Âdem'e öğretilen adlar", "tur": "lugat", "alim": "İbn Atiyye", "alinti": "وعلم آدم الأسماء كلها", "ozet": "Bakara 2:31 ve 'Allah'ın doksan dokuz ismi' hadisi, ismin müsemmâ değil adın kendisi anlamında olduğu örneklerdir.", "iddia": ["I26"], "iliski": "destek"}
{"seg": "IBNATIYYA:1:1", "konu": "ism-müsemmâ: Mâlik", "tur": "kelam", "alim": "Mâlik", "alinti": "فقال ليس به ولا هو غيره", "ozet": "Mâlik'e ism müsemmânın kendisi mi diye sorulunca 'o değildir, başkası da değildir' der.", "iddia": ["I19"], "iliski": "destek"}
{"seg": "IBNATIYYA:1:1", "konu": "Allah lafzı: mürtecel", "tur": "lugat", "alim": "bir grup ehl-i ilim", "alinti": "هو اسم مرتجل لا اشتقاق له من فعل", "ozet": "Allah türetilmeyen, ona konmuş bir addır; elif-lâm tarif için değil, lâzımdır.", "iddia": ["I37"], "iliski": "karsi"}
{"seg": "IBNATIYYA:1:1", "konu": "Allah lafzı: ilâhtan", "tur": "lugat", "alim": "ehl-i ilmin çoğu", "alinti": "وذهب كثير من أهل العلم إلى أنه مشتق من أله الرجل إذا عبد", "ozet": "Allah 'elehe' (ibadet etti) fiilinden türer; Rü'be beyti ve İbn Abbâs'ın 'âliheteke' kıraatinde 'ibadetini' anlamı delildir.", "iddia": ["I37"], "iliski": "destek"}
{"seg": "IBNATIYYA:1:1", "konu": "ilâh'tan Allah'a: hemze düşmesi", "tur": "lugat", "alim": "İbn Atiyye", "alinti": "فقيل حذفت الهمزة حذفا على غير قياس ودخلت الألف واللام للتعظيم على لاه", "ozet": "Hemze kıyassız düşmüş, elif-lâm eklenmiştir; ya da hemzenin harekesi lâma geçip idğâm olmuştur; ilk görüş daha güçlüdür.", "iddia": ["I37"], "iliski": "destek"}
{"seg": "IBNATIYYA:1:1", "konu": "Allah: Halîl, vilâh (şaşakalma)", "tur": "lugat", "alim": "el-Halîl", "alinti": "إلا أنها مأخوذة من وله الرجل إذا تحير", "ozet": "Aslı vilâh sayılır; akıllar Allah'ın sıfatlarının hakikatinde şaşırıp kaldığı için 'velihe' kökündendir.", "iddia": ["I46"], "iliski": "destek"}
{"seg": "IBNATIYYA:1:1", "konu": "Allah lafzında son elifin yazıdan düşmesi", "tur": "nahiv", "alim": "İbn Atiyye", "alinti": "وحذفت الألف الأخيرة من الله لئلا يشكل بخط اللات", "ozet": "Allah'ın son elifi 'Lât' yazısıyla karışmasın diye ya da hafiflik için ya da lehçe olduğu için yazıdan düşmüştür.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA:1:1", "konu": "Rahmân mübalağa sıfatı", "tur": "belagat", "alim": "İbn Atiyye", "alinti": "والرحمن صفة مبالغة من الرحمة ومعناها أنه انتهى إلى غاية الرحمة", "ozet": "Rahmân rahmette en uç noktaya varmayı bildiren mübalağa sıfatıdır, tıpkı sekrân ve gadbân gibi.", "iddia": ["I49"], "iliski": "destek"}
{"seg": "IBNATIYYA:1:1", "konu": "Rahmân yalnız Allah'a özgü", "tur": "belagat", "alim": "İbn Atiyye", "alinti": "وهي صفة تختص بالله ولا تطلق على البشر", "ozet": "Rahmân Allah'a özgü, insana söylenmez; fe'lân kalıbı fe'îlden, fe'îl fâ'ilden daha mübalağalıdır.", "iddia": ["I52"], "iliski": "destek"}
{"seg": "IBNATIYYA:1:1", "konu": "Rahîm: çokluk ve süreklilik", "tur": "belagat", "alim": "İbn Atiyye", "alinti": "ورحيما يقال لمن كثر منه ذلك", "ozet": "Râhim bir kez merhamet edene de denir; rahîm merhameti çok olana; Rahmân rahmette sondur.", "iddia": ["I50"], "iliski": "genisletme"}
{"seg": "IBNATIYYA:1:1", "konu": "Rahmân-Rahîm eş anlamlı", "tur": "nahiv", "alim": "bazı kimseler", "alinti": "بمعنى واحد كالندمان والنديم", "ozet": "İkisi aynı anlamdadır, nedmân ve nedîm gibi, aynı fiilden gelir, yalnız biri daha mübalağalıdır.", "iddia": ["I50"], "iliski": "karsi"}
{"seg": "IBNATIYYA:1:1", "konu": "el-Arzemî: Rahmân genel, Rahîm mü'minlere", "tur": "tefsir_rivayet", "alim": "el-Arzemî", "alinti": "الرحمن بجميع خلقه في الأمطار", "ozet": "Rahmân yağmurlarda, duyu nimetlerinde ve genel nimetlerde bütün yaratıklara, Rahîm mü'minlere hidayet ve lütufla.", "iddia": ["I54", "I61"], "iliski": "genisletme"}
{"seg": "IBNATIYYA:1:1", "konu": "Rahmân dünya ve ahiret, Rahîm ahiret", "tur": "hadis", "alim": "Ebû Saîd el-Hudrî ve İbn Mes'ûd", "alinti": "الرحمن رحمن الدنيا والآخرة والرحيم رحيم الآخرة", "ozet": "Peygamber: Rahmân dünyanın ve ahiretin, Rahîm yalnız ahiretin rahmetidir.", "iddia": [], "iliski": "yeni", "derece": "kaynak derece vermiyor"}
{"seg": "IBNATIYYA:1:1", "konu": "Ebû Ali el-Fârisî: Rahmân genel, Rahîm mü'minlere", "tur": "nahiv", "alim": "Ebû Ali el-Fârisî", "alinti": "الرحمن اسم عام في جميع أنواع الرحمة يختص به الله تعالى", "ozet": "Rahmân her rahmet türünü kapsayan ve Allah'a özgü bir addır; Rahîm mü'minlere yöneliktir (33:43); bu görüşler birbirini destekler.", "iddia": ["I50", "I52"], "iliski": "genisletme"}
{"seg": "IBNATIYYA:1:1", "konu": "Ata el-Horâsânî: Müseylime", "tur": "tarih", "alim": "Atâ el-Horâsânî", "alinti": "وسمي به مسيلمة الكذاب", "ozet": "Rahmân adı Müseylime'ye verilince Allah 'er-Rahmân er-Rahîm'i kendine verdi, ikisinin birlikteliği yalnız ona aittir; İbn Atiyye zayıf bulur çünkü besmele Müseylime'den öncedir.", "iddia": ["I53"], "iliski": "genisletme"}
{"seg": "IBNATIYYA:1:1", "konu": "Araplar Rahmân'ı bilmiyordu iddiası", "tur": "tarih", "alim": "bir grup (İbn Atiyye reddeder)", "alinti": "وإنما وقفت العرب على تعيين الإله الذي أمروا بالسجود له", "ozet": "'Rahmân da nedir' (25:60) sözüne dayanan iddiaya karşı: Araplar lafzı bilmiyor değildi, secde edilecek ilâhın kim olduğunu soruyordu.", "iddia": ["I53"], "iliski": "karsi"}
{"seg": "IBNATIYYA:1:1", "konu": "er-Rahîm'in ardından el-hamd: vasıl kıraati", "tur": "kiraat", "alim": "Ümmü Seleme (Peygamber'den); Kûfeliler", "alinti": "وقرأ به قوم من الكوفيين", "ozet": "Ümmü Seleme rivayetiyle er-Rahîm'in mîmi sükûnlu okunup durulur, el-hamd kat' hemzesiyle başlanır; bazı Kûfeliler böyle okur.", "iddia": [], "iliski": "yeni", "derece": "kaynak derece vermiyor"}
{"seg": "IBNATIYYA:1:1", "konu": "er-Rahîm el-hamd: cumhur ve Kisâî", "tur": "kiraat", "alim": "cumhur; el-Kisâî (bazı Araplardan)", "alinti": "وحكى الكسائي عن بعض العرب", "ozet": "Cumhur er-Rahîmi'l-hamd (cer, vasıl) okur; Kisâî bazı Araplardan er-Rahîme'l-hamd (mîm fetha) aktarır, kimseden kıraat olarak rivayet edilmemiştir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p60", "bos": true, "neden": "yalnız sure metni, yorum yok"}
{"seg": "IBNATIYYA-FULL:v1p60#2", "konu": "Hz. Ca'fer es-Sâdık: besmele sure tacı", "tur": "tefsir_rivayet", "alim": "Cafer b. Muhammed es-Sâdık", "alinti": "البسملة تيجان السور", "ozet": "Besmele surelerin taçlarıdır.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p60#2", "konu": "şeytanı küçülten besmele", "tur": "hadis", "alim": "Hz. Peygamber", "alinti": "فإنه يتعاظم عنده، ولكن قل", "ozet": "'Şeytan helak olsun' deyen adama 'deme, o büyür; besmele de, sinekten küçük olur' der.", "iddia": [], "iliski": "yeni", "derece": "kaynak derece vermiyor"}
{"seg": "IBNATIYYA-FULL:v1p60#2", "konu": "İsrâ 17:46 tefsiri", "tur": "tefsir_rivayet", "alim": "Ali b. el-Hüseyin", "alinti": "معناه إذا قلت", "ozet": "'Rabbini Kur'an'da yalnız andığında sırtlarını dönerler' ayetinin anlamı 'besmele dediğinde' olarak aktarılır.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p60#2", "konu": "Câbir hadisi", "tur": "hadis", "alim": "Câbir b. Abdullah", "alinti": "كيف تفتتح الصلاة يا جابر", "ozet": "Câbir 'el-hamdü lillâhi rabbi'l-âlemîn' deyince Peygamber 'besmele de' der.", "iddia": ["I3"], "iliski": "destek", "derece": "kaynak derece vermiyor"}
{"seg": "IBNATIYYA-FULL:v1p60#2", "konu": "Cebrâil namaz öğretirken besmeleyi cehren okur", "tur": "hadis", "alim": "Ebû Hureyre", "alinti": "أتاني جبريل فعلمني الصلاة فقرأ بسم الله الرحمن الرحيم يجهر بها", "ozet": "Cebrâil namazı öğretirken besmeleyi açıktan okur.", "iddia": [], "iliski": "yeni", "derece": "kaynak derece vermiyor"}
{"seg": "IBNATIYYA-FULL:v1p60#2", "konu": "İbn Atiyye: bu hadisler ayet olduğunu gerektirir, Übey hadisi reddeder", "tur": "fikih", "alim": "İbn Atiyye", "alinti": "وهذان الحديثان يقتضيان أنها آية من الحمد", "ozet": "İki hadis besmelenin Fâtiha'dan ayet olduğunu gerektirir; sahih Übey hadisi (namaza el-hamdü ile başlar), kasame hadisi ve halifelerin ameli bunu reddeder.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p60#2", "konu": "kasame hadisi", "tur": "hadis", "alim": "Hz. Peygamber (Allah'tan)", "alinti": "قسمت الصلاة بيني وبين عبدي", "ozet": "Hadis-i kudsîde Fâtiha'nın kul ile Allah arasında bölünüşü el-hamdü'yle başlar, besmele geçmez.", "iddia": [], "iliski": "yeni", "derece": "sahih (İbn Atiyye 'el-hadîsü's-sahîh' der)"}
{"seg": "IBNATIYYA-FULL:v1p60#2", "konu": "dört halife besmele okumadı", "tur": "fikih", "alim": "İbn Atiyye", "alinti": "ولا عن أبي بكر، ولا عن عمر، ولا عن عثمان", "ozet": "Peygamber, Ebû Bekir, Ömer ve Osman'ın namazlarında besmele okuduğu hıfzedilmemiştir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p60#2", "konu": "ayet sayısı delili ve Hicr 15:87", "tur": "fikih", "alim": "İbn Atiyye", "alinti": "ويرده عدد آيات السورة لأن الإجماع أنها سبع آيات", "ozet": "Ayet sayısı icmâla yedidir; Cu'fî'nin altı ve Amr b. Ubeyd'in sekiz demesi şâzdır.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p60#2", "konu": "Hicr 15:87", "tur": "ayet_ayet", "alim": "İbn Atiyye", "alinti": "ولقد آتيناك سبعا من المثاني", "ozet": "'Sana yedi mesânî verdik' ayeti ayet sayısı tartışmasında hükmü verir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p61", "konu": "Şâfiî", "tur": "fikih", "alim": "Şâfiî", "alinti": "يعد «بسم الله الرحمن الرحيم» آية من الحمد", "ozet": "Şâfiî besmeleyi Fâtiha'dan ayet sayar; Mekke ve Kûfe kurrâsından çoğu 'en'amte aleyhim'i saymaz.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p61", "konu": "Mâlik, Ebû Hanîfe ve cumhur", "tur": "fikih", "alim": "Mâlik, Ebû Hanîfe, fakih ve kurrâ cumhuru", "alinti": "لا يعدون البسملة آية", "ozet": "Cumhur besmeleyi ayet saymaz.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p61", "konu": "Câbir ve Ebû Hureyre hadislerinin yorumu", "tur": "fikih", "alim": "İbn Atiyye", "alinti": "فأمره بالبسملة لهذا لا لأنها آية", "ozet": "Peygamber Câbir'in okumasını öğrenme amaçlı saydığı için besmeleyi emreder, ayet olduğu için değil; Übey'e ise sureyi özel kılmak için söylemez.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p61", "konu": "İbnü'l-Mübârek", "tur": "fikih", "alim": "İbnü'l-Mübârek", "alinti": "وهذا قول شاذ رد الناس عليه", "ozet": "'Besmele her surede ayettir' görüşü şâzdır, insanlar reddetmiştir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p61", "konu": "İsrâ 17:110 inince 'bismillâhi'r-Rahmân' yazıldı", "tur": "nuzul", "alim": "eş-Şa'bî ve el-A'meş", "alinti": "فلما نزلت قل ادعوا الله أو ادعوا الرحمن [الإسراء: 110]", "ozet": "Peygamber önce 'bismike'llâhümme' yazar, 'bismillâh' emredilince onu yazar, İsrâ 110 inince 'bismillâhi'r-Rahmân' yazar.", "iddia": ["I25"], "iliski": "genisletme"}
{"seg": "IBNATIYYA-FULL:v1p61", "konu": "Neml 27:30 inince tam besmele yazıldı", "tur": "nuzul", "alim": "eş-Şa'bî ve el-A'meş", "alinti": "إنه من سليمان وإنه بسم الله الرحمن الرحيم [النمل: 30] كتبها", "ozet": "Neml 30 inince Peygamber besmeleyi tam olarak yazar.", "iddia": ["I5"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p61", "konu": "besmele ilk vahiy: Amr b. Şurahbîl", "tur": "nuzul", "alim": "Amr b. Şurahbîl", "alinti": "أن جبريل أول ما جاء النبي عليه السلام قال له", "ozet": "Cebrâil ilk geldiğinde Peygamber'e 'besmele de' der.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p61", "konu": "besmele ilk vahiy: İbn Abbâs", "tur": "nuzul", "alim": "İbn Abbâs", "alinti": "أن أول ما نزل به جبريل", "ozet": "Cebrâil'in ilk indirdiği besmeledir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p61", "konu": "Hatice hadisinin bazı tarikleri", "tur": "hadis", "alim": "Hatice hadisinin bazı tarikleri", "alinti": "وفي بعض طرق حديث خديجة", "ozet": "Bazı yollarda Cebrâil 'besmele de' der, Peygamber söyler, sonra 'ikra' denir ve 'ben okuyan değilim' der.", "iddia": [], "iliski": "yeni", "derece": "kaynak derece vermiyor"}
{"seg": "IBNATIYYA-FULL:v1p61", "konu": "on dokuz harf ve zebâniler", "tur": "isari", "alim": "bazı kimseler", "alinti": "والبسملة تسعة عشر حرفا", "ozet": "Besmele on dokuz harftir; bazıları zebânilerin on dokuz sayısını (74:30) buna bağlar; her harfe bir melek ve güçleri besmeledendir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p61#2", "konu": "İbn Atiyye: harf sayısı yorumu", "tur": "tefsir_dirayet", "alim": "İbn Atiyye", "alinti": "وهذه من ملح التفسير، وليست من متين العلم", "ozet": "Bu, tefsirin nüktelerindendir, sağlam ilimden değildir; Kadir gecesi ve 'rabbenâ ve lekel-hamd' meleklerinin harf sayımı gibidir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p61#2", "konu": "bâ'nın müteallakı: Basra", "tur": "nahiv", "alim": "Basra nahivcileri", "alinti": "والباء في: بسم الله متعلقة عند نحاة البصرة باسم", "ozet": "Basralılara göre bâ isme bağlıdır (takdir: başlangıcım yerleşiktir bismillâh); mahalli merfûdur.", "iddia": ["I2"], "iliski": "karsi"}
{"seg": "IBNATIYYA-FULL:v1p61#2", "konu": "bâ'nın müteallakı: Kûfe", "tur": "nahiv", "alim": "Kûfe nahivcileri", "alinti": "وعند نحاة الكوفة بفعل تقديره ابتدأت بسم الله", "ozet": "Kûfelilere göre bâ fiile bağlıdır (takdir: başladım bismillâh); mahalli mansûbdur.", "iddia": ["I2"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p61#2", "konu": "Sîbeveyh: bâ isme bağlı", "tur": "nahiv", "alim": "Sîbeveyh", "alinti": "والظاهر من مذهب سيبويه أن الباء متعلقة باسم كما تقدم", "ozet": "Sîbeveyh'e göre bâ isme bağlıdır; bismillâh 'zeyd fi'd-dâr' gibi sabit ya da yerleşik olana bağlanarak mansûb mahaldedir.", "iddia": ["I2"], "iliski": "karsi"}
{"seg": "IBNATIYYA-FULL:v1p61#2", "konu": "bâ'nın kesrelenmesi", "tur": "nahiv", "alim": "İbn Atiyye", "alinti": "وكسرت باء الجر ليناسب لفظها عملها", "ozet": "Cer bâsı lafzı amelle uyuşsun diye, yalnız isimlere girdiği için ya da harf-ism ayrımı için kesrelenmiştir (Â'şâ beyti).", "iddia": ["I1"], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p61#2", "konu": "elifin yazıda düşmesi", "tur": "nahiv", "alim": "İbn Atiyye", "alinti": "وحذفت الألف من بسم الله في الخط اختصارا وتخفيفا لكثرة الاستعمال", "ozet": "Elif sık kullanımdan yazıda düşer; Kisâî ve Ahfeş 'bismi'r-Rahmân'da da düşer der.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p61#2", "konu": "elif yalnız bismillâh'ta düşer: Yahya b. Ziyâd", "tur": "nahiv", "alim": "Yahya b. Ziyâd (el-Ferrâ)", "alinti": "لا تحذف إلا مع بسم الله فقط", "ozet": "Elif yalnız 'bismillâh'ta düşer, çünkü kullanım orada çoktur; İbn Atiyye Allah dışında elifin sabit olduğunda ihtilaf olmadığını söyler.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p61#2", "konu": "ism: Basra sümüvv", "tur": "lugat", "alim": "Basralılar", "alinti": "وهو عند البصريين مشتق من السمو", "ozet": "Basralılara göre ism sümüvvden türer; asıl simv ya da sumv'dur, vâv düşmüş, sîn kesre alıp sükûn bulmuştur.", "iddia": ["I13", "I27"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p62", "konu": "ism: çekimlerden delil", "tur": "lugat", "alim": "Basralılar", "alinti": "وإنما استدل على هذا الأصل الذي ذكرناه بقولهم في التصغير سمي، وفي الجمع أسماء، وفي جمع الجمع أسامي", "ozet": "Küçültme sumey, çoğul esmâ ve çoğulun çoğulu esâmî ismin sümüvv aslını gösterir.", "iddia": ["I27"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p62", "konu": "ism: Kûfe vesm", "tur": "lugat", "alim": "Kûfeliler", "alinti": "وقال الكوفيون: أصل اسم وسم من السمة، وهي العلامة", "ozet": "Kûfelilere göre ism vesmden gelir, çünkü isim konulanın alametidir; fâ'sı kıyassız düşmüştür.", "iddia": ["I30", "I31"], "iliski": "genisletme"}
{"seg": "IBNATIYYA-FULL:v1p62", "konu": "Kûfe görüşünün reddi", "tur": "lugat", "alim": "İbn Atiyye", "alinti": "والتصغير والجمع المذكوران يردان هذا المذهب الكوفي", "ozet": "Anlamca güzel olsa da küçültme ve çoğul onu çürütür; yoksa küçültme 'vesîm', çoğul 'evsâm' olurdu.", "iddia": ["I30"], "iliski": "karsi"}
{"seg": "IBNATIYYA-FULL:v1p62", "konu": "ism-müsemmâ: Taberî", "tur": "kelam", "alim": "et-Taberî", "alinti": "وقال الطبري رحمه الله: إنه ليس بموضع للمسألة", "ozet": "Taberî bunun yeri olmadığını söyler ve kelamcılara hücum eder; İbn Atiyye yine de ismin zâtı ya da adın kendisini kastettiği iki kullanımı ayırır.", "iddia": ["I19"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p62", "konu": "ismin iki kullanımı", "tur": "lugat", "alim": "İbn Atiyye", "alinti": "ففي الأول يقال الاسم هو المسمى بمعنى يراد به المسمى وفي الثاني لا يراد به المسمى", "ozet": "İsimle zât kastedilirse 'ism müsemmâdır'; adın kendisi kastedilirse müsemmâ kastedilmez.", "iddia": ["I19"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p62", "konu": "Rahmân 55:1 ve 'yâ Rahmân'", "tur": "lugat", "alim": "İbn Atiyye", "alinti": "ومن الورود الأول قولك يا رحمن اغفر لي", "ozet": "'Yâ Rahmân beni bağışla' ve Rahmân 55:1 ismin zâtı kastettiği kullanımdır; 'er-Rahmân Allah'ın sıfatıdır' ise ikinci kullanımdır.", "iddia": ["I25"], "iliski": "genisletme"}
{"seg": "IBNATIYYA-FULL:v1p62", "konu": "ism, zât, nefs, ayn", "tur": "lugat", "alim": "İbn Atiyye; ehl-i ilmin çoğu", "alinti": "يقال: ذات، ونفس، واسم، وعين، بمعنى", "ozet": "Arapçada bunlar aynı anlamda söylenir; çoğu âlim A'lâ 87:1'i ve Rahmân 55:78'i böyle anlar.", "iddia": ["I18"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p62", "konu": "Yûsuf 12:40", "tur": "ayet_ayet", "alim": "İbn Atiyye", "alinti": "ما تعبدون من دونه إلا أسماء سميتموها أنتم وآباؤكم [يوسف: 40]", "ozet": "'Allah'tan başka taptıklarınız sizin ve atalarınızın taktığı adlardan başka değildir' ayeti ismi zât anlamına almanın örneği olarak anılır.", "iddia": ["I28"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p62", "konu": "Lebîd beyti", "tur": "lugat", "alim": "Lebîd (ehl-i ilim delil getirir)", "alinti": "وقالوا: إن لبيدا أراد التحية", "ozet": "Lebîd 'ismü's-selâm' derken selâmı kastetmiştir; ism burada fazladır.", "iddia": ["I19"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p62", "konu": "Bakara 2:31: ismin adlar anlamında kullanımı", "tur": "ayet_ayet", "alim": "İbn Atiyye", "alinti": "وعلم آدم الأسماء كلها [البقرة: 31] على أشهر التأويلات فيه", "ozet": "Âdem'e adların öğretilmesi, ismin müsemmâ yerine adın kendisi olduğu örnek; en meşhur te'villerden.", "iddia": ["I26"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p62", "konu": "Allah'ın doksan dokuz ismi", "tur": "hadis", "alim": "Hz. Peygamber", "alinti": "إن لله تسعة وتسعين اسما، مائة إلا واحدا من أحصاها دخل الجنة", "ozet": "Allah'ın doksan dokuz ismini sayan cennete girer; isim burada adın kendisidir.", "iddia": ["I26"], "iliski": "genisletme", "derece": "kaynak derece vermiyor"}
{"seg": "IBNATIYYA-FULL:v1p62", "konu": "Mâlik: ism müsemmâ mıdır", "tur": "kelam", "alim": "Mâlik", "alinti": "ليس به ولا هو غيره", "ozet": "Mâlik'e ismin müsemmâ olup olmadığı sorulunca 'o değildir, başkası da değildir' der; İbn Atiyye iki kullanımla uyuşur görür.", "iddia": ["I19"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p62", "konu": "Allah en bâhir ve en çok kullanılan ad", "tur": "lugat", "alim": "İbn Atiyye", "alinti": "أبهر أسماء الله تعالى وأكثرها استعمالا", "ozet": "Allah lafzı Allah'ın adlarının en parlağı ve en çok kullanılanıdır; öteki adlar çoğunlukla sıfat olarak gelir.", "iddia": ["I40"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p63", "konu": "Allah: mürtecel", "tur": "lugat", "alim": "bir grup ehl-i ilim", "alinti": "هو اسم مرتجل، لا اشتقاق له من فعل", "ozet": "Allah türetilmeyen, ona konmuş bir addır; elif-lâm tarif için değil lâzımdır.", "iddia": ["I37"], "iliski": "karsi"}
{"seg": "IBNATIYYA-FULL:v1p63", "konu": "Allah: elehe", "tur": "lugat", "alim": "ehl-i ilmin çoğu", "alinti": "وذهب كثير من أهل العلم إلى أنه مشتق من أله الرجل إذا عبد، وتأله إذا تنسك", "ozet": "Allah 'elehe' (ibadet etti) ve 'te'elleha' (nüsük yaptı) fiilinden türer; Rü'be beyti delil.", "iddia": ["I37"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p63", "konu": "A'râf 7:127 kıraati ve İbn Abbâs", "tur": "kiraat", "alim": "İbn Abbâs ve başkaları (en-Nakkâş'tan)", "alinti": "فإن ابن عباس وغيره قال: وعبادتك", "ozet": "'ve âliheteke' kıraatinde İbn Abbâs 've ibâdeteke' der; Allah ismi her yaratığın ibadet ettiği anlamında bu fiilden türetilir.", "iddia": ["I37"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p63", "konu": "ilâh'tan Allah'a", "tur": "lugat", "alim": "İbn Atiyye", "alinti": "فقيل: حذفت الهمزة حذفا على غير قياس", "ozet": "Hemze kıyassız düşmüş, elif-lâm eklenmiştir; ya hemze harekesi lâma geçip idğâm olmuştur; ya aslı 'lâh'tır; ilk görüş daha güçlüdür.", "iddia": ["I37"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p63", "konu": "Halîl: ilâh aslı vilâh", "tur": "lugat", "alim": "el-Halîl", "alinti": "وروي عن الخليل أن أصل إله ولاه وأن الهمزة مبدلة من واو", "ozet": "Halîl'e göre ilâhın aslı vilâhtır, hemze vâvdan bedeldir (işâh-vişâh, isâde-visâde gibi).", "iddia": ["I37"], "iliski": "karsi"}
{"seg": "IBNATIYYA-FULL:v1p63", "konu": "Allah: velihe (şaşakalma)", "tur": "lugat", "alim": "İbn Atiyye (Halîl'e uyarak)", "alinti": "إلا أنها مأخوذة من وله الرجل إذا تحير", "ozet": "Akıllar Allah'ın sıfatlarının hakikatinde ve O'nu bilmede şaşırıp kaldığı için 'velihe' kökünden alınmıştır.", "iddia": ["I46"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p63", "konu": "Allah lafzında son elif", "tur": "nahiv", "alim": "İbn Atiyye", "alinti": "وحذفت الألف الأخيرة من «الله» لئلا يشكل بخط اللات", "ozet": "Son elif 'Lât' yazısıyla karışmasın diye, ya da hafiflik için, ya da lehçe olduğu için düşmüştür.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p63", "konu": "Rahmân mübalağa sıfatı", "tur": "belagat", "alim": "İbn Atiyye", "alinti": "والرحمن صفة مبالغة من الرحمة، ومعناها أنه انتهى إلى غاية الرحمة", "ozet": "Rahmân rahmette en uç noktaya varmayı bildirir, sekrân ve gadbân gibi.", "iddia": ["I49"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p63", "konu": "Rahmân yalnız Allah'a özgü; fe'lân, fe'îl, fâ'il", "tur": "belagat", "alim": "İbn Atiyye", "alinti": "وهي صفة تختص بالله ولا تطلق على البشر، وهي أبلغ من فعيل", "ozet": "Rahmân Allah'a özgüdür, insana söylenmez, fe'îlden daha mübalağalıdır.", "iddia": ["I52"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p63", "konu": "Rahîm çokluk, Rahmân nihayet", "tur": "belagat", "alim": "İbn Atiyye", "alinti": "لأن راحما يقال لمن رحم ولو مرة واحدة، ورحيما يقال لمن كثر منه ذلك", "ozet": "Râhim bir kez merhamet edene denir, rahîm çok merhamet edene; Rahmân rahmette sondur.", "iddia": ["I50"], "iliski": "genisletme"}
{"seg": "IBNATIYYA-FULL:v1p63", "konu": "Rahmân-Rahîm eş anlamlı", "tur": "nahiv", "alim": "bazı kimseler", "alinti": "بمعنى واحد، كالندمان والنديم", "ozet": "İkisi aynı anlamdadır, nedmân ve nedîm gibi, aynı fiilden gelir; yalnız biri daha mübalağalıdır.", "iddia": ["I50"], "iliski": "karsi"}
{"seg": "IBNATIYYA-FULL:v1p63#2", "konu": "el-Arzemî: Rahmân genel, Rahîm mü'minlere", "tur": "tefsir_rivayet", "alim": "el-Arzemî", "alinti": "الرحمن بجميع خلقه في الأمطار، ونعم الحواس، والنعم العامة، الرحيم بالمؤمنين في الهداية لهم، واللطف بهم", "ozet": "Rahmân yağmur, duyu ve genel nimetlerde tüm yaratıklara, Rahîm mü'minlere hidayet ve lütufla.", "iddia": ["I54", "I61"], "iliski": "genisletme"}
{"seg": "IBNATIYYA-FULL:v1p63#2", "konu": "Rahmân dünya ve ahiret, Rahîm ahiret", "tur": "hadis", "alim": "Ebû Saîd el-Hudrî ve İbn Mes'ûd", "alinti": "الرحمن رحمن الدنيا والآخرة، والرحيم رحيم الآخرة", "ozet": "Peygamber: Rahmân dünya ve ahiretin, Rahîm yalnız ahiretin rahmetidir.", "iddia": [], "iliski": "yeni", "derece": "kaynak derece vermiyor"}
{"seg": "IBNATIYYA-FULL:v1p63#2", "konu": "Ebû Ali el-Fârisî: Rahmân genel, Rahîm mü'minlere", "tur": "nahiv", "alim": "Ebû Ali el-Fârisî", "alinti": "الرحمن اسم عام في جميع أنواع الرحمة يختص به الله تعالى", "ozet": "Rahmân her rahmet türünü kapsayan Allah'a özgü addır; Rahîm mü'minlere yöneliktir (33:43); bu görüşler birbirini destekler.", "iddia": ["I50", "I52"], "iliski": "genisletme"}
{"seg": "IBNATIYYA-FULL:v1p63#2", "konu": "Atâ el-Horâsânî: Müseylime", "tur": "tarih", "alim": "Atâ el-Horâsânî", "alinti": "فلما اختزل وسمي به مسيلمة الكذاب", "ozet": "Rahmân adı Müseylime'ye verilince Allah 'er-Rahmân er-Rahîm'i kendine verdi; birlikteliği yalnız Allah'a aittir.", "iddia": ["I53"], "iliski": "genisletme"}
{"seg": "IBNATIYYA-FULL:v1p63#2", "konu": "İbn Atiyye: Müseylime görüşü zayıf", "tur": "tefsir_dirayet", "alim": "İbn Atiyye", "alinti": "وهذا قول ضعيف، لأن بسم الله الرحمن الرحيم كان قبل أن ينجم أمر مسيلمة", "ozet": "Besmele Müseylime'nin ortaya çıkışından öncedir; onun bu adı taşıması da yerleşmiş bir şey değildi.", "iddia": ["I53"], "iliski": "karsi"}
{"seg": "IBNATIYYA-FULL:v1p63#2", "konu": "Araplar Rahmân'ı bilmiyordu", "tur": "tarih", "alim": "bir grup", "alinti": "وقال قوم: إن العرب كانت لا تعرف لفظة الرحمن، ولا كانت في لغتها", "ozet": "Bir grup, 'Rahmân da nedir' sözünden (25:60) Arapların bu lafzı bilmediğini çıkarır.", "iddia": ["I53"], "iliski": "destek"}
{"seg": "IBNATIYYA-FULL:v1p63#2", "konu": "İbn Atiyye'nin cevabı", "tur": "tarih", "alim": "İbn Atiyye", "alinti": "وإنما وقفت العرب على تعيين الإله الذي أمروا بالسجود له، لا على نفس اللفظة", "ozet": "Araplar lafzı değil, secde edilecek ilâhın kimliğini sorguluyordu.", "iddia": ["I53"], "iliski": "karsi"}
{"seg": "IBNATIYYA-FULL:v1p63#2", "konu": "er-Rahîm'in ardından el-hamd: vasıl", "tur": "kiraat", "alim": "Ümmü Seleme (Peygamber'den); Kûfeliler; cumhur", "alinti": "وقرأ به قوم من الكوفيين", "ozet": "Ümmü Seleme rivayetiyle mîm sükûnlu okunup durulur, el-hamd kat' hemzesiyle başlanır; cumhur er-Rahîmi'l-hamd (cer, vasıl) okur.", "iddia": [], "iliski": "yeni", "derece": "kaynak derece vermiyor"}
{"seg": "IBNATIYYA-FULL:v1p63#2", "konu": "Kisâî: mîm fethalı vasıl", "tur": "kiraat", "alim": "el-Kisâî (bazı Araplardan)", "alinti": "وحكى الكسائي عن بعض العرب أنها تقرأ", "ozet": "Bazı Araplardan er-Rahîme'l-hamd (mîm fetha) okunduğu aktarılır; kimseden kıraat olarak rivayet edilmemiştir.", "iddia": [], "iliski": "yeni"}
{"seg": "IBNATIYYA-FULL:v1p65", "bos": true, "neden": "sure adları ve fazileti, ayetle ilgisiz"}
{"seg": "IBNATIYYA-FULL:v1p71", "bos": true, "neden": "din kelimesi ve 1:4 yorumu"}
{"seg": "IBNATIYYA-FULL:v1p71#2", "bos": true, "neden": "din ve 1:5 iyyâke yorumu"}
{"seg": "IBNATIYYA-FULL:v1p72", "bos": true, "neden": "1:5 iyyâke na'büdü yorumu"}
{"seg": "IBNATIYYA-FULL:v1p73", "bos": true, "neden": "1:5-6 istiâne ve hidâyet, ayetle ilgisiz"}
{"seg": "IBNATIYYA-FULL:v1p73#2", "bos": true, "neden": "1:6 hidâyet ve sırât yorumu"}
{"seg": "IBNATIYYA-FULL:v1p74", "bos": true, "neden": "1:6 sırât-ı müstakîm yorumu"}
{"seg": "IBNATIYYA-FULL:v1p76", "bos": true, "neden": "1:7 gayri'l-mağdûbi aleyhim kıraati"}
{"seg": "IBNATIYYA-FULL:v1p77", "bos": true, "neden": "1:7 mağdûb ve dâllîn yorumu"}
{"seg": "IBNATIYYA-FULL:v1p78#2", "konu": "Fâtiha ayet sayısı yedi", "tur": "kiraat", "alim": "İbn Atiyye (halkın icmâı)", "alinti": "وأجمع الناس على أن عدد آي سورة الحمد سبع آيات", "ozet": "Fâtiha'nın yedi ayet olduğunda icmâ vardır; ayetler el-âlemîn, er-Rahîm, ed-dîn, nesta'în, el-müstakîm, en'amte aleyhim, ve ledâllîn ile biter; besmele hakkındaki zayıf ihtilaf önce anıldı.", "iddia": [], "iliski": "yeni"}
